import { Spot } from './spots'

/** Spots generated by `npm run fetch:data` (empty until the script has been run) */
export async function loadWikidataSpots(): Promise<Spot[]> {
  try {
    const res = await fetch(`${import.meta.env.BASE_URL}data/spots-wikidata.json`)
    if (!res.ok) return []
    const data = await res.json()
    return Array.isArray(data) ? data : []
  } catch {
    return []
  }
}

function distanceKm(a: Spot, b: Spot) {
  const R = 6371
  const rad = Math.PI / 180
  const dLat = (b.lat - a.lat) * rad
  const dLng = (b.lng - a.lng) * rad
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(a.lat * rad) * Math.cos(b.lat * rad) * Math.sin(dLng / 2) ** 2
  return 2 * R * Math.asin(Math.sqrt(h))
}

const norm = (s: string) => s.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').trim()

/**
 * Curated spots win. A Wikidata spot with the same English name enriches the curated one
 * (photo, UNESCO flag); one that is merely close by (< 2km) is dropped as a duplicate.
 */
export function mergeSpots(curated: Spot[], extra: Spot[]): Spot[] {
  const result = curated.map((s) => ({ ...s }))
  const byName = new Map(result.map((s) => [norm(s.nameEn), s]))

  for (const w of extra) {
    const same = byName.get(norm(w.nameEn))
    if (same) {
      same.image ??= w.image
      same.unesco ||= w.unesco
      continue
    }
    if (result.some((s) => distanceKm(s, w) < 2)) continue
    result.push(w)
  }
  return result
}
